 
 CREATE TABLE IF NOT EXISTS users(id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,password TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('student','supervisor','admin')),approved INTEGER NOT NULL DEFAULT 1);
 CREATE TABLE IF NOT EXISTS projects(id BIGSERIAL PRIMARY KEY,title TEXT NOT NULL,abstract TEXT NOT NULL,area TEXT NOT NULL,student_id INTEGER NOT NULL REFERENCES users(id),supervisor_id INTEGER NOT NULL REFERENCES users(id),status TEXT NOT NULL DEFAULT 'Proposed',progress INTEGER NOT NULL DEFAULT 0,created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
 CREATE TABLE IF NOT EXISTS submissions(id BIGSERIAL PRIMARY KEY,project_id INTEGER NOT NULL REFERENCES projects(id),title TEXT NOT NULL,filename TEXT NOT NULL,content BYTEA NOT NULL,created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
 CREATE TABLE IF NOT EXISTS reviews(id BIGSERIAL PRIMARY KEY,project_id INTEGER NOT NULL REFERENCES projects(id),author_id INTEGER NOT NULL REFERENCES users(id),comment TEXT NOT NULL,decision TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
 CREATE TABLE IF NOT EXISTS deadlines(id BIGSERIAL PRIMARY KEY,title TEXT NOT NULL,due_date TEXT NOT NULL,description TEXT NOT NULL);
 CREATE TABLE IF NOT EXISTS notifications(id BIGSERIAL PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),message TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
 CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),expires BIGINT NOT NULL);
 CREATE TABLE IF NOT EXISTS audit(id BIGSERIAL PRIMARY KEY,user_id INTEGER REFERENCES users(id),action TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
 